// Generated table accessor for Android-added UI text. The table itself is
// generated by dm/android/tools/strings.py from the same bilingual TSV that
// produces the Java resources; no labels or measurements are hardcoded here.
#include "android_ui_text.h"

#include "android_ui_strings.h"

#include <stddef.h>
#include <string.h>

const char *dm_android_ui_text(const char *key, int zh) {
    if (!key) return NULL;
    for (size_t i = 0; i < sizeof k_dm_android_i18n / sizeof k_dm_android_i18n[0]; ++i)
        if (!strcmp(k_dm_android_i18n[i].key, key))
            return zh ? k_dm_android_i18n[i].zh : k_dm_android_i18n[i].en;
    return NULL;
}
